mapper.sql:
WHERE 1=1
AND r.book_id=#{filter.bookId}
AND (u.nickname LIKE CONCAT('%',#{filter.keyword},'%') OR u.short_id LIKE CONCAT('%',#{filter.keyword},'%') OR u.mobile LIKE CONCAT('%',#{filter.keyword},'%') OR b.book_name LIKE CONCAT('%',#{filter.keyword},'%'))
AND r.selected_at >= #{filter.from}
AND r.selected_at < #{filter.until}
